      const rootId = (identity && identity.rootId) || store.sessionId || ''
      const leadEntry = list.find(a => a.name === 'lead' || (rootId && a.id === rootId)) || null
      const allChildren = list.filter(a => a !== leadEntry && a.name !== 'lead')
